mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="Fresh Pantry offers unique, high-quality food products at great prices. Discover featured picks and find a store near you." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #fdf9f1;
      --surface: #fffdf8;
      --surface-2: #f5efdf;
      --text: #223224;
      --muted: #5a705d;
      --primary: #2f7a47;
      --primary-deep: #245f37;
      --accent: #e7984d;
      --accent-2: #f2cf58;
      --ring: rgba(47, 122, 71, 0.28);
      --shadow: 0 10px 30px rgba(42, 68, 47, 0.12);
      --radius-xl: 24px;
      --radius-lg: 18px;
      --radius-md: 14px;
      --container: min(1140px, 92vw);
    }

    * { box-sizing: border-box; }
    html, body {
      margin: 0;
      padding: 0;
      background: radial-gradient(circle at top right, #fff9df 0%, var(--bg) 38%, #fcf7ef 100%);
      color: var(--text);
      font-family: "Plus Jakarta Sans", "Segoe UI", sans-serif;
      scroll-behavior: smooth;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }

    .container { width: var(--container); margin: 0 auto; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      backdrop-filter: blur(10px);
      background: rgba(253, 249, 241, 0.85);
      border-bottom: 1px solid rgba(47, 122, 71, 0.12);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.9rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.7rem;
      font-family: "Nunito", sans-serif;
      font-size: 1.25rem;
      font-weight: 800;
      color: var(--primary-deep);
    }

    .brand-badge {
      width: 38px;
      height: 38px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: linear-gradient(130deg, var(--accent-2), var(--accent));
      box-shadow: var(--shadow);
      font-size: 1.1rem;
    }

    .nav {
      display: flex;
      gap: 1.25rem;
      align-items: center;
      flex-wrap: wrap;
    }

    .nav a {
      color: var(--muted);
      font-weight: 600;
      transition: color 0.25s ease;
    }

    .nav a:hover,
    .nav a:focus-visible { color: var(--primary); }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: 0.72rem 1.15rem;
      font-weight: 700;
      font-family: inherit;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.25s ease, background 0.25s ease;
    }

    .btn:focus-visible, input:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 2px;
    }

    .btn-primary {
      background: var(--primary);
      color: #fff;
      box-shadow: 0 8px 22px rgba(47, 122, 71, 0.28);
    }

    .btn-primary:hover { transform: translateY(-1px); background: var(--primary-deep); }

    .hero {
      padding: 4.8rem 0 3.2rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.08fr 0.92fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding: 0.35rem 0.7rem;
      background: #e8f5ea;
      border-radius: 999px;
      color: var(--primary-deep);
      font-size: 0.86rem;
      font-weight: 700;
      margin-bottom: 1rem;
    }

    h1, h2, h3 { font-family: "Nunito", sans-serif; line-height: 1.08; margin: 0; }

    h1 {
      font-size: clamp(2.2rem, 5.4vw, 4.2rem);
      letter-spacing: -0.02em;
    }

    .hero p {
      margin: 1.2rem 0 1.6rem;
      font-size: 1.06rem;
      color: var(--muted);
      max-width: 58ch;
      line-height: 1.65;
    }

    .hero-visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow);
      min-height: 430px;
    }

    .hero-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-chip {
      position: absolute;
      bottom: 1rem;
      left: 1rem;
      background: rgba(255, 255, 255, 0.9);
      backdrop-filter: blur(5px);
      border-radius: 14px;
      padding: 0.7rem 0.85rem;
      box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);
      font-size: 0.92rem;
      font-weight: 700;
      color: var(--primary-deep);
    }

    .section { padding: 2.4rem 0; }

    .section-head {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1rem;
    }

    .section-head h2 { font-size: clamp(1.6rem, 3.1vw, 2.4rem); }
    .section-head p { margin: 0; color: var(--muted); max-width: 48ch; }

    .carousel-wrap {
      background: linear-gradient(140deg, #f6efdc, #fffaf0);
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      box-shadow: var(--shadow);
      border: 1px solid rgba(47, 122, 71, 0.08);
    }

    .carousel-top {
      display: flex;
      justify-content: flex-end;
      gap: 0.5rem;
      margin-bottom: 0.75rem;
    }

    .arrow-btn {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      border: 0;
      font-size: 1.35rem;
      background: #fff;
      color: var(--primary-deep);
      box-shadow: 0 6px 14px rgba(0, 0, 0, 0.1);
      cursor: pointer;
      transition: transform 0.2s ease, background 0.25s ease;
    }

    .arrow-btn:hover { transform: translateY(-1px); background: #f3ffef; }

    .carousel-viewport {
      overflow: hidden;
      border-radius: var(--radius-lg);
    }

    .carousel-track {
      display: flex;
      gap: 1rem;
      transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
      will-change: transform;
    }

    .product-card {
      min-width: calc((100% - 2rem) / 3);
      background: var(--surface);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: 0 8px 16px rgba(45, 79, 45, 0.1);
      border: 1px solid rgba(33, 66, 36, 0.08);
    }

    .product-card img { height: 190px; width: 100%; object-fit: cover; }

    .product-meta { padding: 0.9rem; }
    .product-meta h3 { font-size: 1.08rem; margin-bottom: 0.45rem; }
    .price { color: var(--primary-deep); font-weight: 800; }

    .stats-banner {
      margin-top: 1.9rem;
      background: linear-gradient(135deg, #245f37, #367d4f 65%, #4f9a69);
      color: #f8fff6;
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
      padding: 1.3rem;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .stat-item {
      background: rgba(255,255,255,0.08);
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
    }

    .stat-number {
      font-family: "Nunito", sans-serif;
      font-size: clamp(1.4rem, 2.6vw, 2.05rem);
      font-weight: 800;
      line-height: 1;
      margin-bottom: 0.4rem;
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .season-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      position: relative;
      min-height: 260px;
      box-shadow: var(--shadow);
    }

    .season-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(17, 31, 19, 0.7), rgba(17, 31, 19, 0.08));
    }

    .season-card img { width: 100%; height: 100%; object-fit: cover; }
    .season-content {
      position: absolute;
      z-index: 2;
      left: 1rem;
      right: 1rem;
      bottom: 1rem;
      color: #fff;
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 0.85rem;
    }

    .category-card {
      position: relative;
      border-radius: 16px;
      overflow: hidden;
      min-height: 200px;
      cursor: pointer;
      box-shadow: var(--shadow);
      transform: translateZ(0);
      transition: transform 0.28s ease;
    }

    .category-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.42s ease;
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(18, 32, 19, 0.68), rgba(18, 32, 19, 0.2));
      display: flex;
      align-items: end;
      padding: 0.85rem;
      color: #fff;
      font-family: "Nunito", sans-serif;
      font-size: 1.06rem;
      font-weight: 700;
      transition: background 0.28s ease;
    }

    .category-card:hover,
    .category-card:focus-within { transform: scale(1.03); }

    .category-card:hover img,
    .category-card:focus-within img { transform: scale(1.08); }

    .category-card:hover .category-overlay,
    .category-card:focus-within .category-overlay {
      background: linear-gradient(to top, rgba(36, 95, 55, 0.76), rgba(36, 95, 55, 0.28));
    }

    .locator,
    .newsletter {
      background: var(--surface);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
      padding: 1.4rem;
      border: 1px solid rgba(47, 122, 71, 0.1);
    }

    .form-row {
      display: flex;
      gap: 0.6rem;
      margin-top: 1rem;
      flex-wrap: wrap;
    }

    input {
      flex: 1;
      min-width: 220px;
      border: 1px solid rgba(47, 122, 71, 0.2);
      border-radius: 999px;
      padding: 0.72rem 1rem;
      font: inherit;
      background: #fff;
    }

    .store-results {
      margin-top: 1rem;
      display: none;
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid rgba(47, 122, 71, 0.16);
    }

    .store-results.active { display: block; }

    table {
      width: 100%;
      border-collapse: collapse;
      background: #fff;
      font-size: 0.95rem;
    }

    th, td {
      padding: 0.72rem;
      border-bottom: 1px solid rgba(47, 122, 71, 0.1);
      text-align: left;
      vertical-align: top;
    }

    th { background: #f3f8f2; color: var(--primary-deep); font-size: 0.85rem; letter-spacing: 0.02em; }

    .newsletter-wrap {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      align-items: center;
    }

    .confirm {
      margin-top: 0.8rem;
      color: var(--primary-deep);
      font-weight: 700;
      display: none;
    }

    .confirm.active { display: block; }

    footer {
      margin-top: 2.3rem;
      background: #1f3a26;
      color: #e5f2e7;
      padding: 2.1rem 0;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .footer-grid h3 { font-size: 1rem; margin-bottom: 0.55rem; }
    .footer-grid a { color: #d3e8d7; display: inline-block; margin: 0.22rem 0; }
    .footer-grid a:hover { color: #fff; }

    .tagline {
      margin: 0;
      border-top: 1px solid rgba(212, 232, 217, 0.2);
      padding-top: 1rem;
      color: #d8ebdc;
      font-size: 0.92rem;
    }

    @media (max-width: 1024px) {
      .hero-grid, .newsletter-wrap { grid-template-columns: 1fr; }
      .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
      .stats-banner { grid-template-columns: repeat(2, 1fr); }
      .product-card { min-width: calc((100% - 1rem) / 2); }
    }

    @media (max-width: 720px) {
      .header-inner { flex-wrap: wrap; }
      .nav { order: 2; width: 100%; justify-content: center; }
      .hero { padding-top: 3rem; }
      .seasonal-grid { grid-template-columns: 1fr; }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-banner { grid-template-columns: 1fr; }
      .product-card { min-width: 100%; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      table, thead, tbody, th, td, tr { display: block; }
      thead { display: none; }
      td {
        border-bottom: 0;
        position: relative;
        padding-left: 45%;
      }
      td::before {
        content: attr(data-label);
        position: absolute;
        left: 0.72rem;
        width: 40%;
        font-weight: 700;
        color: var(--primary-deep);
      }
      tr { border-bottom: 1px solid rgba(47, 122, 71, 0.14); }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a href="index.html" class="brand" aria-label="Fresh Pantry Home">
        <span class="brand-badge">🍋</span>
        Fresh Pantry
      </a>
      <nav class="nav" aria-label="Main navigation">
        <a href="index.html#featured-products">Products</a>
        <a href="index.html#store-locator">Our Stores</a>
        <a href="index.html#seasonal-picks">Recipes</a>
        <a href="index.html#footer">About Us</a>
      </nav>
      <button class="btn btn-primary" type="button" onclick="document.getElementById('store-locator').scrollIntoView({behavior:'smooth'})">Find a Store</button>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">🌿 Local Feel, Big Flavor</span>
          <h1>Discover Everyday <br/>Deliciousness.</h1>
          <p>
            Fresh Pantry brings your neighborhood grocery adventure online — stocked with quality pantry staples, fun seasonal finds, and feel-good favorites at wallet-friendly prices.
          </p>
          <button class="btn btn-primary" type="button" onclick="document.getElementById('featured-products').scrollIntoView({behavior:'smooth'})">Shop Featured Picks</button>
        </div>
        <div class="hero-visual">
          <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="Colorful produce and pantry aisle" loading="eager">
          <div class="hero-chip">Weekly favorites starting at $2.99</div>
        </div>
      </div>
    </section>

    <section class="section" id="featured-products">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Featured Products</h2>
            <p>Fresh discoveries this week — curated for snackers, meal-preppers, and flavor seekers.</p>
          </div>
        </div>

        <div class="carousel-wrap" aria-label="Featured products carousel">
          <div class="carousel-top">
            <button class="arrow-btn" id="prevBtn" aria-label="Previous products">‹</button>
            <button class="arrow-btn" id="nextBtn" aria-label="Next products">›</button>
          </div>
          <div class="carousel-viewport">
            <div class="carousel-track" id="productTrack">
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=900&q=80" alt="Organic Maple Granola">
                <div class="product-meta">
                  <h3>Organic Maple Granola</h3>
                  <div class="price">$5.99</div>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=900&q=80" alt="Everything But The Bagel Seasoning">
                <div class="product-meta">
                  <h3>Everything But The Bagel Seasoning</h3>
                  <div class="price">$2.49</div>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1606312619070-d48b4c652a52?auto=format&fit=crop&w=900&q=80" alt="Dark Chocolate Peanut Butter Cups">
                <div class="product-meta">
                  <h3>Dark Chocolate Peanut Butter Cups</h3>
                  <div class="price">$4.29</div>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80" alt="Cauliflower Gnocchi">
                <div class="product-meta">
                  <h3>Cauliflower Gnocchi</h3>
                  <div class="price">$3.79</div>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1600891964599-f61ba0e24092?auto=format&fit=crop&w=900&q=80" alt="Mandarin Orange Chicken">
                <div class="product-meta">
                  <h3>Mandarin Orange Chicken</h3>
                  <div class="price">$6.49</div>
                </div>
              </article>
            </div>
          </div>
        </div>

        <div class="stats-banner" aria-label="Brand highlights">
          <div class="stat-item">
            <div class="stat-number">500+</div>
            <div>Stores Nationwide</div>
          </div>
          <div class="stat-item">
            <div class="stat-number">4,000+</div>
            <div>Unique Products</div>
          </div>
          <div class="stat-item">
            <div class="stat-number">80%</div>
            <div>Private Label Items</div>
          </div>
          <div class="stat-item">
            <div class="stat-number">New Weekly</div>
            <div>Fresh Discoveries</div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="seasonal-picks">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Seasonal Picks</h2>
            <p>Cozy flavors and bright produce for this season’s easiest, most delicious meals.</p>
          </div>
        </div>
        <div class="seasonal-grid">
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1478145046317-39f10e56b5e9?auto=format&fit=crop&w=1000&q=80" alt="Seasonal fruits and vegetables">
            <div class="season-content">
              <h3>Harvest Produce</h3>
              <p>Peak-season fruits and veggies picked for flavor.</p>
            </div>
          </article>
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1482049016688-2d3e1b311543?auto=format&fit=crop&w=1000&q=80" alt="Healthy breakfast bowls">
            <div class="season-content">
              <h3>Morning Staples</h3>
              <p>Feel-good breakfast picks for busy weekdays.</p>
            </div>
          </article>
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1466637574441-749b8f19452f?auto=format&fit=crop&w=1000&q=80" alt="Prepared meal ingredients">
            <div class="season-content">
              <h3>Easy Dinner Wins</h3>
              <p>Fast freezer finds and pantry heroes for dinner.</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="categories">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Browse Categories</h2>
            <p>Hover to explore your next favorite aisle.</p>
          </div>
        </div>
        <div class="categories-grid">
          <a class="category-card" href="#" aria-label="Snacks & Sweets category">
            <img src="https://images.unsplash.com/photo-1587393855524-087f83d95ac7?auto=format&fit=crop&w=900&q=80" alt="Snacks and sweets">
            <div class="category-overlay">Snacks &amp; Sweets</div>
          </a>
          <a class="category-card" href="#" aria-label="Fresh Produce category">
            <img src="https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=80" alt="Fresh produce">
            <div class="category-overlay">Fresh Produce</div>
          </a>
          <a class="category-card" href="#" aria-label="Frozen Favorites category">
            <img src="https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=900&q=80" alt="Frozen favorites">
            <div class="category-overlay">Frozen Favorites</div>
          </a>
          <a class="category-card" href="#" aria-label="Beverages category">
            <img src="https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=900&q=80" alt="Beverages">
            <div class="category-overlay">Beverages</div>
          </a>
          <a class="category-card" href="#" aria-label="Dairy and cheese category">
            <img src="https://images.unsplash.com/photo-1550583724-b2692b85b150?auto=format&fit=crop&w=900&q=80" alt="Dairy and cheese">
            <div class="category-overlay">Dairy &amp; Cheese</div>
          </a>
        </div>
      </div>
    </section>

    <section class="section" id="store-locator">
      <div class="container locator">
        <div class="section-head" style="margin-bottom:0;">
          <div>
            <h2>Find a Fresh Pantry Near You</h2>
            <p>Discover the nearest store, hours, and directions.</p>
          </div>
        </div>
        <div class="form-row">
          <input type="text" id="zipInput" placeholder="Enter your zip code" aria-label="Zip code">
          <button class="btn btn-primary" id="searchStoreBtn" type="button">Search</button>
        </div>
        <div class="store-results" id="storeResults" aria-live="polite">
          <table>
            <thead>
              <tr>
                <th>Store Name</th>
                <th>Address</th>
                <th>Hours</th>
                <th>Distance</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td data-label="Store Name">Fresh Pantry — Lincoln Park</td>
                <td data-label="Address">2140 N. Halsted St, Chicago, IL 60614</td>
                <td data-label="Hours">8am – 9pm Daily</td>
                <td data-label="Distance">0.8 mi</td>
              </tr>
              <tr>
                <td data-label="Store Name">Fresh Pantry — Wicker Park</td>
                <td data-label="Address">1840 W. North Ave, Chicago, IL 60622</td>
                <td data-label="Hours">8am – 9pm Daily</td>
                <td data-label="Distance">1.4 mi</td>
