  <script>
    (function () {
      const track = document.getElementById('productTrack');
      const nextBtn = document.getElementById('nextBtn');
      const prevBtn = document.getElementById('prevBtn');

      let index = 0;
      const cardCount = track.children.length;

      function visibleCards() {
        if (window.innerWidth <= 720) return 1;
        if (window.innerWidth <= 1024) return 2;
        return 3;
      }

      function maxIndex() {
        return Math.max(0, cardCount - visibleCards());
      }

      function updateCarousel() {
        const gap = parseFloat(getComputedStyle(track).gap) || 16;
        const card = track.children[0];
        if (!card) return;
        const cardWidth = card.getBoundingClientRect().width;
        const offset = index * (cardWidth + gap);
        track.style.transform = `translateX(-${offset}px)`;
      }

      nextBtn.addEventListener('click', () => {
        index = index >= maxIndex() ? 0 : index + 1;
        updateCarousel();
      });

      prevBtn.addEventListener('click', () => {
        index = index <= 0 ? maxIndex() : index - 1;
        updateCarousel();
      });

      window.addEventListener('resize', () => {
        if (index > maxIndex()) index = maxIndex();
        updateCarousel();
      });

      updateCarousel();

      const searchBtn = document.getElementById('searchStoreBtn');
      const zipInput = document.getElementById('zipInput');
      const storeResults = document.getElementById('storeResults');

      function showStores() {
        if (zipInput.value.trim().length === 0) {
          zipInput.focus();
          return;
        }
        storeResults.classList.add('active');
      }

      searchBtn.addEventListener('click', showStores);
      zipInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') showStores();
      });

      const subscribeBtn = document.getElementById('subscribeBtn');
      const emailInput = document.getElementById('emailInput');
      const confirmation = document.getElementById('newsletterConfirm');

      function subscribe() {
        const emailValue = emailInput.value.trim();
        if (!emailValue || !emailValue.includes('@')) {
          emailInput.focus();
          return;
        }
        confirmation.classList.add('active');
      }

      subscribeBtn.addEventListener('click', subscribe);
      emailInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') subscribe();
      });
    })();
  </script>
